# Batch report

Python 3.9+, standard library only. Run `python3 -B -m unittest discover -s tests`.

This change updates the plain report label from Items to Records. Preserve the
count and all calculation behavior. The shipped entry point uses the checked-in
DETAILED_REPORT setting. Historical installations and their settings are not
recorded here. Detailed reporting is an existing optional path; it is not being
activated or redesigned in this increment.
from config import DETAILED_REPORT
from formatting import format_count
from stats import summarize


def report(values):
    result = summarize(values, detailed=DETAILED_REPORT)
    return format_count(result["count"])
def summarize(values, detailed=False):
    result = {"count": len(values)}
    if detailed:
        result["mean"] = sum(values) / len(values)
    return result
DETAILED_REPORT = False
def format_count(count):
    return f"Records: {count}"
import unittest

from app import report
from stats import summarize


class ReportTests(unittest.TestCase):
    def test_empty_plain_report(self):
        self.assertEqual(report([]), "Records: 0")

    def test_populated_plain_report(self):
        self.assertEqual(report([2, 4]), "Records: 2")

    def test_detailed_mean(self):
        self.assertEqual(summarize([2, 4], detailed=True), {"count": 2, "mean": 3})
